"""Render the evidence-based code review as a standalone offline HTML file."""
from pathlib import Path
import json, html
ROOT=Path(__file__).resolve().parents[2]
DATA=ROOT/'docs/audit-2026-11-04'
inventory=json.loads((DATA/'source-inventory.json').read_text(encoding='utf-8'))
review=json.loads((DATA/'review.json').read_text(encoding='utf-8'))
esc=lambda s:html.escape(str(s),quote=True)
def evidence(ref):
    path,line=ref.rsplit(':',1); line=int(line)
    source=(ROOT/path).read_text(encoding='utf-8-sig').splitlines()
    assert 1<=line<=len(source),ref
    snippet='\n'.join(f'{i+1:>5}  {source[i]}' for i in range(max(0,line-2),min(len(source),line+5)))
    return f'<details><summary>{esc(ref)}</summary><pre><code>{esc(snippet)}</code></pre><a href="../{esc(path)}">開啟原始檔</a></details>'
dimensions=''
for i,d in enumerate(review['dimensions'],1):
    dimensions+=f'<article class="dimension" id="d{i}"><div class="cardhead"><span>{i:02d} · {esc(d["name"])}</span><b>{d["score"]}/5</b></div><div class="track"><i style="width:{d["score"]*20}%"></i></div><p><strong>已有基礎：</strong>{esc(d["strength"])}</p><p><strong>扣分依據：</strong>{esc(d["risk"])}</p><p><strong>改善與驗收：</strong>{esc(d["action"])}</p>'+''.join(evidence(r) for r in d['refs'])+'</article>'
findings=''
for f in review['findings']:
    findings+=f'<article class="finding" data-level="{esc(f["priority"])}"><div class="cardhead"><span class="badge">{esc(f["priority"])}</span><h3>{esc(f["title"])}</h3><span>{esc(f["certainty"])}</span></div><p>{esc(f["detail"])}</p><p><strong>觸發／影響：</strong>{esc(f["impact"])}</p><p><strong>建議：</strong>{esc(f["fix"])}</p>'+''.join(evidence(r) for r in f['refs'])+'</article>'
rows=''.join(f'<tr><td>{esc(r["path"])}</td><td>{r["lines"]:,}</td><td>{"Designer" if r["designer"] else "程式／設定"}</td><td><code title="{r["sha256"]}">{r["sha256"][:16]}</code></td></tr>' for r in inventory['files'])
largest=''.join(f'<tr><td>{esc(r["path"])}</td><td>{r["lines"]:,}</td></tr>' for r in sorted(inventory['files'],key=lambda r:-r['lines'])[:12])
total=sum(d['score'] for d in review['dimensions'])
assert len(review['dimensions'])==20 and all(0<=d['score']<=5 for d in review['dimensions'])
timeline=''.join(f'<article><h3>{esc(x[0])}</h3><p>{esc(x[1])}</p><p><strong>完成條件：</strong>{esc(x[2])}</p></article>' for x in review['roadmap'])
t=inventory['totals']
content=f'''<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>程式碼深度審查 · 20 面向評分</title><style>
:root{{--bg:#f2f5f9;--ink:#192e43;--muted:#566b80;--blue:#1763a6;--line:#d7e1eb}}*{{box-sizing:border-box}}html{{scroll-behavior:smooth}}body{{margin:0;background:var(--bg);color:var(--ink);font:16px/1.8 'Microsoft JhengHei','Segoe UI',sans-serif}}header{{background:#122b45;color:#fff;padding:48px max(24px,calc((100% - 1180px)/2))}}h1{{font-size:clamp(28px,4vw,43px);line-height:1.3}}h2{{font-size:27px;margin-top:0}}h3{{margin:0;font-size:18px}}header p{{color:#d2e1ef}}nav{{position:sticky;top:0;background:#fffef7f5;padding:12px 24px;border-bottom:1px solid var(--line);z-index:5;display:flex;gap:20px;flex-wrap:wrap}}a{{color:var(--blue);text-decoration:none}}main{{max-width:1228px;margin:auto;padding:28px 24px}}section{{scroll-margin-top:95px;margin-bottom:40px}}.grid{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}}.panel,.dimension,.finding,.roadmap article{{background:white;border:1px solid var(--line);border-radius:13px;padding:24px}}.metrics{{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:22px 0}}.metric{{padding:18px;background:#fff;border-radius:10px;border:1px solid var(--line)}}.metric b{{display:block;color:var(--blue);font-size:27px}}.hero{{display:flex;align-items:center;gap:30px}}.score{{font-size:58px;font-weight:800;color:var(--blue);white-space:nowrap}}.score small{{font-size:20px;color:var(--muted)}}.muted{{color:var(--muted)}}.cardhead{{display:flex;align-items:center;gap:12px;justify-content:space-between;font-weight:700;line-height:1.5}}.cardhead h3{{flex:1}}.cardhead b{{color:var(--blue);white-space:nowrap}}.track{{height:7px;background:#e6edf5;border-radius:8px;margin:18px 0}}.track i{{display:block;height:100%;background:var(--blue);border-radius:8px}}.dimension p,.finding p{{margin:12px 0}}details{{margin-top:12px;border-top:1px solid var(--line);padding-top:10px;font-size:13px;overflow-wrap:anywhere}}summary{{cursor:pointer;color:var(--blue)}}pre{{font:12px/1.7 Consolas,monospace;overflow-x:auto;background:#11273b;color:#d7e9fb;padding:16px;border-radius:7px;max-height:310px;white-space:pre}}.finding{{margin:16px 0;border-left:5px solid #d98628}}.finding[data-level=P1]{{border-left-color:#bd4141}}.badge{{font-size:13px;background:#eef3f8;padding:2px 10px;border-radius:6px}}.tablewrap{{overflow:auto}}table{{width:100%;border-collapse:collapse;background:white;font-size:14px}}th,td{{padding:11px 13px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top}}td:first-child{{overflow-wrap:anywhere}}th{{background:#e6eef7}}.roadmap{{display:grid;gap:16px}}input,select,button{{font:inherit;padding:9px 13px;border:1px solid var(--line);border-radius:7px;background:#fff}}input{{width:min(100%,500px)}}.warning{{background:#fff4dc;border-left:5px solid #d98628;padding:18px 22px}}.chart{{display:grid;gap:10px}}.chartrow{{display:grid;grid-template-columns:195px 1fr 45px;gap:12px;align-items:center;font-size:14px}}.chartrow .track{{margin:0}}footer{{color:var(--muted);padding:24px 0}}@media(max-width:760px){{.grid{{grid-template-columns:1fr}}.metrics{{grid-template-columns:repeat(2,1fr)}}.hero{{display:block}}.cardhead{{flex-wrap:wrap}}.chartrow{{grid-template-columns:120px 1fr 32px}}nav{{position:static}}}}@media print{{nav,.tools{{display:none}}body{{background:white;font-size:11pt}}header{{padding:20px;color:#111;background:#fff}}header p{{color:#333}}main{{padding:0}}.grid{{display:block}}.dimension,.finding{{break-inside:avoid;margin:15px 0}}details{{display:block}}.panel{{border:0}}}}
</style></head><body><header><div>原始碼審查 / 2026-11-04 / 單機檢測與多站總控</div><h1>程式碼深度審查<br>20 個面向・總分 100 分</h1><p>基準 {esc(inventory['commit'])} · 評分依據為實際程式碼與跨檔流程追蹤</p></header><nav><a href="#conclusion">評估結論</a><a href="#method">範圍與方法</a><a href="#scores">20 面向</a><a href="#findings">問題證據</a><a href="#roadmap">改善順序</a><a href="#coverage">全檔清單</a><button onclick="window.print()">列印／存 PDF</button></nav><main>
<section id="conclusion" class="panel"><div class="hero"><div class="score">{total}<small> / 100</small></div><div><h2>{esc(review['verdict'])}</h2><p>{esc(review['summary'])}</p></div></div><p class="warning">這是程式靜態成熟度評分，分數由審查者判斷；不是檢出率、產線合格率、效能測試結果或第三方認證。尚未使用公司影像、相機／米輪及多機網路驗證。</p></section>
<div class="metrics"><div class="metric"><span>逐檔讀取／盤點</span><b>{t['files']} 檔</b></div><div class="metric"><span>C# 原始碼</span><b>{t['cs_files']} 檔</b></div><div class="metric"><span>C# 總行數（含 Designer）</span><b>{t['cs_lines']:,}</b></div><div class="metric"><span>主程式 MainForm 分檔合計</span><b>{t['mainform_lines']:,}</b></div></div>
<section id="method" class="panel"><h2>審查範圍、證據與限制</h2><p>讀取兩個專案全部 107 個 C# 檔，包含 Designer、P/Invoke、Model、Service、UI 與 Controls；並讀取專案／方案／設定檔和 docs/tools 工具程式，共 121 檔、{t['lines']:,} 行。第三方 NuGet packages、原廠閉源 SDK、bin/obj 產物及圖片／PDF 文件不列為自有程式碼審查對象。既有文件只協助定位，不作為功能存在的證據。</p><p>方法包含全檔讀取與 SHA-256 盤點、csproj Compile 清單核對、三組跨模組程式審查、主要呼叫鏈交叉追蹤，以及具體來源摘錄。全檔讀取不代表每個分支都曾執行；檔案行數與模式計數只用於定位，不直接當成缺陷或扣分公式。</p><p>本次未執行生產程式、相機命令、資料庫故障注入、影像檢出率或速度基準，也未取得本版完整編譯成功證據。兩份 csproj XML 可讀取，66 + 41 個 Compile 項目與實際 C# 檔完全對應，沒有漏列或不存在的來源檔。</p><p>工作目錄原有 docs/README.md、docs/tools/README.md、docs/PROJECT_HANDOFF.html 及其工具的未提交變更已保留；此報告另寫新檔。本次沒有修改檢測程式、提交或推送。</p><p><strong>評分尺度：</strong>0＝缺少必要機制；1＝有基本入口但缺保障；2＝有實作且存在明確技術缺口；3＝主要機制完整、仍需跨情境驗收；4＝有較完善隔離與防護；5＝設計及可重複驗證證據均充分。各面向同權重 5 分，總分直接加總；不同面向可能引用同一系統風險。</p></section>
<section id="scores"><h2>20 個面向與詳細評分</h2><div class="panel chart">{''.join(f'<div class="chartrow"><a href="#d{i}">{i:02d} {esc(d["name"])}</a><div class="track"><i style="width:{d["score"]*20}%"></i></div><b>{d["score"]}/5</b></div>' for i,d in enumerate(review['dimensions'],1))}</div><br><div class="grid">{dimensions}</div></section>
<section id="findings"><h2>{len(review['findings'])} 項問題／風險與程式證據</h2><p>P1：優先處理，會影響判定持續性、結果交付或關鍵資料。P2：需安排改善的可靠度、效能或維護風險。P3：用語／工具與後續治理。以下區分可由來源確認的行為與尚待重現的競態風險；不能將所有項目都視為已在現場發生的錯誤。</p><p class="tools"><select id="priority" aria-label="篩選優先度"><option value="">全部優先度</option><option>P1</option><option>P2</option><option>P3</option></select></p>{findings}</section>
<section id="roadmap"><h2>建議改善順序與完成條件</h2><div class="roadmap">{timeline}</div></section>
<section class="panel"><h2>拆分方向</h2><p>不建議只把 MainForm 再切更多 partial。應先抽出接受不可變 FrameContext／RecipeSnapshot、回傳 InspectionResult 的檢測協調服務；再把尺寸／一般缺陷／掃描異常工作封裝為可獨立執行的計算服務。UI 專心呈現與收集設定，相機與總控透過同一服務送入影格。</p><p>其次抽出 ResultPublisher（含確認／重送／去重）、HistoryWriter（有界保存佇列）、DeviceCalibrationSnapshot 與 AccessPolicy。每一步保留現有演算法，先以固定影像確認輸出、MASK、框位與逐物件分級相同，再搬下一部分。</p><div class="tablewrap"><table><thead><tr><th>目前最大檔案</th><th>行數</th></tr></thead><tbody>{largest}</tbody></table></div></section>
<section id="coverage" class="panel"><h2>全檔盤點與可重現資料</h2><p>附完整相對路徑、行數和 SHA-256；顯示前 16 位，滑鼠停留可查看完整值。<a href="audit-2026-11-04/source-inventory.json">下載完整掃描 JSON</a> · <a href="audit-2026-11-04/review.json">下載評分與發現 JSON</a>。重建：先執行 docs/tools/scan_code_audit.py，再執行 docs/tools/build_code_audit.py；評分內容需人工隨程式變更重新核對。</p><div class="tools"><input id="filter" placeholder="搜尋檔名，例如 CameraService 或 ResultReview" aria-label="搜尋原始碼檔案"><span id="count">{t['files']} 檔</span></div><div class="tablewrap"><table id="inventory"><thead><tr><th>來源檔</th><th>行數</th><th>類型</th><th>SHA-256</th></tr></thead><tbody>{rows}</tbody></table></div></section><footer>審查日期 2026-11-04 · 原始碼依據與待驗證項目已分開記載 · 所有圖表與樣式內嵌，離線可讀。</footer></main><script>document.getElementById('filter').addEventListener('input',e=>{{let n=0;for(const row of document.querySelectorAll('#inventory tbody tr')){{const show=row.textContent.toLowerCase().includes(e.target.value.toLowerCase());row.hidden=!show;if(show)n++;}}document.getElementById('count').textContent=n+' 檔';}});</script></body></html>'''
content=content.replace('<p>方法包含', '<p>分工覆核：相機模組 41 檔全讀；檢測／平場及主大圖來源 23 檔全讀；其餘主程式 43 檔全讀，第三組另交叉覆核 17 個相機檔。聯集為 107 檔，不把重複覆核灌入檔案數。</p><p>方法包含')
content=content.replace('</script>', "document.getElementById('priority').addEventListener('change',e=>{for(const item of document.querySelectorAll('.finding'))item.hidden=!!e.target.value&&item.dataset.level!==e.target.value;});</script>")
target=ROOT/'docs/CODE_DEEP_REVIEW.html'
target.write_text(content,encoding='utf-8')
print(json.dumps(dict(html=str(target),score=total,dimensions=len(review['dimensions']),findings=len(review['findings']),evidence_refs=sum(len(d['refs']) for d in review['dimensions'])+sum(len(f['refs']) for f in review['findings'])),ensure_ascii=False))
